# two Branches, two Workspaces, one Sandbox
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  console.log("fork docs", (await lf.branch.fork("docs")).kind);
  console.log("fork site", (await lf.branch.fork("site")).kind);
  const { sandbox } = await lf.sandbox.create();
  const docs = await lf.workspace.mount(sandbox, "docs");
  const site = await lf.workspace.mount(sandbox, "site");
  console.log(JSON.stringify({ sandbox, docs: docs.path, site: site.path }));
  const guide = await lf.workspace.exec(docs, "mkdir -p docs && cp README.md docs/guide.md && sed -i 's/Website/Guide/' docs/guide.md && cat docs/guide.md");
  console.log(`docs$ write docs/guide.md\n${guide.stdout}${guide.stderr}`);
  const install = await lf.workspace.exec(site, "sh install.sh");
  console.log(`site$ sh install.sh\n${install.stdout}${install.stderr}`);
  const look = await lf.workspace.exec(site, "test -f docs/guide.md && echo 'site sees docs/guide.md' || echo 'site cannot see docs/guide.md: separate overlays'");
  console.log(`site$ test -f docs/guide.md\n${look.stdout}${look.stderr}`);
} finally {
  await lf.close();
}
