# an fs write beside a mounted Workspace; unmount of a building one
node --input-type=module <<'JS'
const { LayerFS, isRefusal } = await import("@layerfs/agent");
const { LayerFSBackend } = await import("@layerfs/backend");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
const be = LayerFSBackend.of(lf);
try {
  console.log("fs.write CHANGELOG.md on docs (docs is mounted) →", (await lf.fs.write("docs", "/CHANGELOG.md", "- docs guide\n", "changelog")).kind);
  const { items } = await lf.sandbox.list_workspaces("{{sandbox}}");
  const siteAt = items.find((w) => w.branch === "site");
  const site = { sandbox: siteAt.sandbox, path: siteAt.path };
  const ready = await lf.workspace.exec(site, "timeout 20 sh -c 'until [ -f .build-ready ]; do sleep 0.05; done'");
  if (ready.exitCode !== 0) throw new Error("background build did not become ready within 20 seconds");
  // The build touches .build-ready before its start call returns; unmount refuses Busy only for a listed process.
  const listedBy = Date.now() + 20000;
  while (!(await be.daemon.process.list()).items.some((p) => p.sandbox === site.sandbox && p.path === site.path && p.status === "running")) {
    if (Date.now() >= listedBy) throw new Error("background build was not listed as running within 20 seconds");
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  let refusedBusy = false;
  try {
    await lf.workspace.unmount(site);
  } catch (error) {
    if (!isRefusal(error, "Busy")) throw error;
    refusedBusy = true;
    console.log(`unmount site while it builds → refused ${error.code}: ${error.message}`);
  }
  if (!refusedBusy) throw new Error("unmount must refuse Busy while the build holds its file open");
  const released = await lf.workspace.exec(site, "touch .build-release");
  if (released.exitCode !== 0) throw new Error("could not release the ready build");
} finally {
  await lf.close();
}
