# teardown, one explicit step at a time
node --input-type=module <<'JS'
const { LayerFS, isRefusal } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { items } = await lf.sandbox.list_workspaces("{{sandbox}}");
  const docsAt = items.find((w) => w.branch === "docs");
  const docs = { sandbox: docsAt.sandbox, path: docsAt.path };
  const siteAt = items.find((w) => w.branch === "site");
  const site = { sandbox: siteAt.sandbox, path: siteAt.path };
  const c = await lf.workspace.commit(docs, "docs guide");
  console.log(`commit docs → ${c.kind}${c.merged ? " (merged with the head first)" : ""}`);
  console.log("unmount docs →", (await lf.workspace.unmount(docs)).kind);
  try {
    await lf.sandbox.close("{{sandbox}}");
  } catch (error) {
    if (!isRefusal(error, "MountsActive")) throw error;
    console.log(`close Sandbox {{sandbox}} → refused ${error.code}: ${error.message}`);
  }
  try {
    await lf.workspace.unmount(site);
  } catch (error) {
    if (!isRefusal(error, "Dirty")) throw error;
    console.log(`unmount site → refused ${error.code}: ${(error.detail?.changed ?? []).slice(0, 4).join(", ")}`);
  }
  console.log("unmount site, discarding the build output →", (await lf.workspace.unmount(site, true)).kind);
  console.log("close Sandbox {{sandbox}} →", (await lf.sandbox.close("{{sandbox}}")).kind);
  try {
    await lf.sandbox.close("{{sandbox}}");
  } catch (error) {
    if (!isRefusal(error, "NoSuchSandbox")) throw error;
    console.log(`close Sandbox {{sandbox}} again → refused ${error.code}`);
  }
  console.log("fs.write README.md on docs →", (await lf.fs.write("docs", "/README.md", "# Website docs\n", "docs readme")).kind);
  console.log("docs /:", (await lf.fs.list("docs", "/")).items.map((e) => e.name).join(" "));
} finally {
  await lf.close();
}
